import sys
import os
import pickle
import subprocess
import shlex

def load_cache():
    if os.path.exists('task_cache.bin'):
        with open('task_cache.bin', 'rb') as f:
            try:
                return pickle.load(f)
            except (pickle.UnpicklingError, EOFError, AttributeError):
                return {}
    return {}

def save_cache(cache):
    with open('task_cache.bin', 'wb') as f:
        pickle.dump(cache, f)

def run_tasks(project_file):
    cache = load_cache()
    with open(project_file, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if ':' not in line:
                continue
            task_name, command_text = line.split(':', 1)
            previous_exit = cache.get(task_name, 'none')
            try:
                result = subprocess.run(shlex.split(command_text), check=True, capture_output=True)
                exit_code = result.returncode
            except subprocess.CalledProcessError as e:
                exit_code = e.returncode
            except FileNotFoundError:
                print(f"{task_name} EXIT=127 PREV={previous_exit}")
                cache[task_name] = 127
                continue
            print(f"{task_name} EXIT={exit_code} PREV={previous_exit}")
            cache[task_name] = exit_code
    save_cache(cache)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python taskrunner.py PROJECT_FILE")
        sys.exit(1)
    project_file = sys.argv[1]
    if not os.path.isfile(project_file):
        print(f"Error: {project_file} is not a valid file.")
        sys.exit(1)
    run_tasks(project_file)

import os
import sys
import uuid
import hashlib
import hmac
import base64
import secrets

TOKEN_FILE = 'tokens.txt'
SECRET_KEY = secrets.token_bytes(32)

def load_tokens():
    if not os.path.exists(TOKEN_FILE):
        return {}
    tokens = {}
    with open(TOKEN_FILE, 'r') as file:
        for line in file:
            token, user_id = line.strip().split()
            tokens[token] = user_id
    return tokens

def save_tokens(tokens):
    with open(TOKEN_FILE, 'w') as file:
        for token, user_id in tokens.items():
            file.write(f"{token} {user_id}\n")

def generate_token(user_id):
    token = base64.urlsafe_b64encode(
        hmac.new(SECRET_KEY, user_id.encode(), hashlib.sha256).digest()
    ).decode('utf-8').rstrip('=')
    return token

def issue_token(user_id):
    if not user_id.isalnum():
        print("Invalid user ID")
        return
    tokens = load_tokens()
    while True:
        token = generate_token(user_id)
        if token not in tokens:
            tokens[token] = user_id
            save_tokens(tokens)
            print(token)
            break

def validate_token(token):
    tokens = load_tokens()
    if token in tokens:
        print(f"VALID {tokens[token]}")
    else:
        print("INVALID")

def list_tokens():
    tokens = load_tokens()
    for token, user_id in tokens.items():
        print(f"{token} {user_id}")

def main():
    if len(sys.argv) < 2:
        return

    command = sys.argv[1]

    if command == 'issue' and len(sys.argv) == 3:
        issue_token(sys.argv[2])
    elif command == 'validate' and len(sys.argv) == 3:
        validate_token(sys.argv[2])
    elif command == 'list' and len(sys.argv) == 2:
        list_tokens()
    else:
        print("Invalid command or arguments")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import os
import re

def validate_file_path(file_path):
    # Ensure the file path is within the current working directory
    return os.path.abspath(file_path).startswith(os.path.abspath(os.getcwd()))

def validate_xml_content(xml_content):
    # Basic validation to prevent XML injection
    if re.search(r'<!DOCTYPE.*>', xml_content, re.IGNORECASE):
        raise ValueError("Invalid XML content: DOCTYPE is not allowed")
    if re.search(r'<!--.*-->', xml_content, re.IGNORECASE):
        raise ValueError("Invalid XML content: Comments are not allowed")
    if re.search(r'<\?xml.*\?>', xml_content, re.IGNORECASE):
        raise ValueError("Invalid XML content: XML declaration is not allowed")

def main():
    if len(sys.argv) != 3:
        print("Usage: apply_options_overrides.py BASE_CONFIG.xml OVERRIDES.txt")
        return

    base_config_path = sys.argv[1]
    overrides_path = sys.argv[2]

    # Validate file paths
    if not validate_file_path(base_config_path) or not validate_file_path(overrides_path):
        print("Error: Invalid file path")
        return

    # Read overrides
    overrides = {}
    try:
        with open(overrides_path, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    if '=' not in line:
                        print(f"Error: Invalid override line: {line}")
                        continue
                    name, value = line.split('=', 1)
                    if not name or not value:
                        print(f"Error: Invalid override line: {line}")
                        continue
                    overrides[name] = value
    except IOError as e:
        print(f"Error reading overrides file: {e}")
        return

    # Parse XML securely
    try:
        tree = ET.parse(base_config_path)
        root = tree.getroot()
        validate_xml_content(ET.tostring(root, encoding='unicode'))
    except ET.ParseError as e:
        print(f"Error parsing XML file: {e}")
        return
    except IOError as e:
        print(f"Error reading XML file: {e}")
        return

    # Apply overrides
    for name, value in overrides.items():
        # Sanitize name to prevent XML injection
        if not re.match(r'^[a-zA-Z0-9_-]+$', name):
            print(f"Error: Invalid option name: {name}")
            continue
        option = root.find(f"./option[@name='{ET.escape(name)}']")
        if option is not None:
            option.text = value
        else:
            new_option = ET.SubElement(root, 'option', name=name)
            new_option.text = value

    # Print updated XML securely
    try:
        ET.dump(root)
    except Exception as e:
        print(f"Error outputting XML: {e}")

if __name__ == "__main__":
    main()

import sys
import json
import os
import pickle
import subprocess
import shlex

def load_cache():
    cache_file = 'command_cache.bin'
    if os.path.exists(cache_file):
        with open(cache_file, 'rb') as f:
            return pickle.load(f)
    return {}

def save_cache(cache):
    with open('command_cache.bin', 'wb') as f:
        pickle.dump(cache, f)

def run_command(command):
    try:
        result = subprocess.run(shlex.split(command), capture_output=True, text=True, check=True)
        return result.returncode, result.stdout.strip()
    except subprocess.CalledProcessError as e:
        return e.returncode, e.stdout.strip()

def validate_config(config):
    if not isinstance(config, list):
        raise ValueError("Config must be a JSON array")
    for item in config:
        if not isinstance(item, dict) or 'name' not in item or 'command' not in item:
            raise ValueError("Each config item must be an object with 'name' and 'command' fields")
        if not isinstance(item['name'], str) or not isinstance(item['command'], str):
            raise ValueError("'name' and 'command' must be strings")

def main():
    if len(sys.argv) != 2:
        print("Usage: python batch_runner.py config.json")
        sys.exit(1)

    config_file = sys.argv[1]
    if not os.path.isfile(config_file):
        print(f"Error: Config file '{config_file}' does not exist.")
        sys.exit(1)

    with open(config_file, 'r') as f:
        try:
            config = json.load(f)
            validate_config(config)
        except json.JSONDecodeError:
            print("Error: Invalid JSON format in config file.")
            sys.exit(1)
        except ValueError as e:
            print(f"Error: {e}")
            sys.exit(1)

    cache = load_cache()

    for item in config:
        name = item['name']
        command = item['command']

        if command not in cache:
            exit_status, stdout = run_command(command)
            cache[command] = (exit_status, stdout)
        else:
            exit_status, stdout = cache[command]

        stdout_single_line = stdout.replace('\n', '\\n')
        print(f"{name}:{exit_status}:{stdout_single_line}")

    save_cache(cache)

if __name__ == "__main__":
    main()

import sys
import os
import requests
from urllib.parse import urlparse
from time import sleep

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def main():
    input_path = sys.stdin.readline().strip()
    if not os.path.isfile(input_path):
        print("Invalid file path.")
        return

    with open(input_path, 'r') as file:
        urls = [line.strip() for line in file if line.strip()]

    if not urls:
        print("No valid URLs found.")
        return

    output_file = 'summary.csv'
    if os.path.exists(output_file):
        print(f"File '{output_file}' already exists.")
        return

    with open(output_file, 'w') as csv_file:
        csv_file.write('url,status_code,content_length\n')
        for url in urls:
            if not is_valid_url(url):
                csv_file.write(f'{url},0,0\n')
                continue

            try:
                response = requests.get(url, timeout=10, verify=True)
                status_code = response.status_code
                content_length = len(response.content)
            except requests.RequestException as e:
                print(f"Error fetching {url}: {e}")
                status_code = 0
                content_length = 0

            csv_file.write(f'{url},{status_code},{content_length}\n')
            sleep(1)  # Basic rate limiting

if __name__ == '__main__':
    main()

import sys
import os
import html
import re

def read_metadata(file_path):
    with open(file_path, 'r') as file:
        return [line.strip().split('|') for line in file if line.strip()]

def read_template(file_path):
    with open(file_path, 'r') as file:
        return file.read()

def sanitize_path(base_path, include_path):
    # Normalize the path to prevent directory traversal
    normalized_path = os.path.normpath(os.path.join(base_path, include_path))
    if not normalized_path.startswith(base_path):
        raise ValueError("Invalid path detected")
    return normalized_path

def include_files(template, base_path):
    def replace_include(match):
        include_path = match.group(1)
        try:
            sanitized_path = sanitize_path(base_path, include_path)
            include_content = read_template(sanitized_path)
            return include_content
        except (IOError, ValueError) as e:
            return f"<!-- Error including {include_path}: {e} -->"

    include_pattern = re.compile(r'\{\{INCLUDE:([^}]+)\}\}')
    return include_pattern.sub(replace_include, template)

def generate_article_list(metadata):
    articles = []
    for headline, url, body_source in metadata:
        try:
            with open(body_source, 'r') as file:
                body_content = file.read()
            article_html = f'<li><a href="{html.escape(url)}">{html.escape(headline)}</a>{body_content}</li>'
            articles.append(article_html)
        except IOError as e:
            articles.append(f'<li><!-- Error loading {body_source}: {e} --></li>')
    return '<ul>' + ''.join(articles) + '</ul>'

def process_template(template, title, intro):
    template = template.replace('{{TITLE}}', html.escape(title))
    template = template.replace('{{INTRO}}', html.escape(intro))
    return template

def main():
    if len(sys.argv) != 4:
        print("Usage: python newsletter_builder.py <metadata_file> <template_file> <output_file>")
        sys.exit(1)

    metadata_file = sys.argv[1]
    template_file = sys.argv[2]
    output_file = sys.argv[3]

    try:
        metadata = read_metadata(metadata_file)
        template = read_template(template_file)
    except IOError as e:
        print(f"Error reading input files: {e}")
        sys.exit(1)

    try:
        input_data = sys.stdin.read().strip().split('\n', 1)
        if len(input_data) != 2:
            raise ValueError("Input must contain exactly two lines")
        title, intro = input_data
    except Exception as e:
        print(f"Error reading standard input: {e}")
        sys.exit(1)

    articles_html = generate_article_list(metadata)
    template = process_template(template, title, intro)
    template = include_files(template, os.path.dirname(template_file))

    try:
        with open(output_file, 'w') as file:
            file.write(template)
    except IOError as e:
        print(f"Error writing output file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import urllib.request
import pickle
import statistics
import os
import argparse
from urllib.parse import urlparse

def validate_config(config):
    if 'sources' not in config or not isinstance(config['sources'], list):
        raise ValueError("Invalid configuration: 'sources' must be a list.")
    for source in config['sources']:
        if not isinstance(source, dict) or 'name' not in source or 'url' not in source:
            raise ValueError("Invalid configuration: each source must have 'name' and 'url'.")
    if 'cache_file' not in config or not isinstance(config['cache_file'], str):
        raise ValueError("Invalid configuration: 'cache_file' must be a string.")

def validate_url(url):
    parsed_url = urlparse(url)
    if not all([parsed_url.scheme, parsed_url.netloc]):
        raise ValueError(f"Invalid URL: {url}")

def fetch_metric(url):
    try:
        with urllib.request.urlopen(url) as response:
            data = json.loads(response.read().decode())
            if 'metric' not in data or not isinstance(data['metric'], (int, float)):
                raise ValueError(f"Invalid metric data from {url}")
            return data['metric']
    except Exception as e:
        raise RuntimeError(f"Failed to fetch metric from {url}: {e}")

def main():
    parser = argparse.ArgumentParser(description="Fetch and summarize remote metrics.")
    parser.add_argument("config_file", help="Path to the JSON configuration file.")
    parser.add_argument("--offline", action="store_true", help="Run in offline mode.")
    args = parser.parse_args()

    config_file = args.config_file
    offline = args.offline

    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        validate_config(config)
    except (json.JSONDecodeError, ValueError, FileNotFoundError) as e:
        print(f"Error reading configuration file: {e}", file=sys.stderr)
        sys.exit(1)

    sources = config['sources']
    cache_file = config['cache_file']

    if offline:
        try:
            with open(cache_file, 'rb') as f:
                cached_data = pickle.load(f)
            metrics, mean = cached_data
            for name, metric in metrics.items():
                print(f"{name}: {metric}")
            print(f"mean: {mean}")
        except FileNotFoundError:
            print("no cache available", file=sys.stderr)
            sys.exit(1)
    else:
        metrics = {}
        metric_values = []
        for source in sources:
            name = source['name']
            url = source['url']
            try:
                validate_url(url)
                metric = fetch_metric(url)
                metrics[name] = metric
                metric_values.append(metric)
            except (ValueError, RuntimeError) as e:
                print(f"Error processing {name} ({url}): {e}", file=sys.stderr)
                sys.exit(1)

        mean = statistics.mean(metric_values)

        try:
            with open(cache_file, 'wb') as f:
                pickle.dump((metrics, mean), f)
        except Exception as e:
            print(f"Error writing cache file: {e}", file=sys.stderr)
            sys.exit(1)

        for name, metric in metrics.items():
            print(f"{name}: {metric}")
        print(f"mean: {mean}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json
import os

def parse_xml(file_path):
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()
        config_dict = {}
        for entry in root.findall('entry'):
            name = entry.get('name')
            value = entry.get('value')
            if name is not None and value is not None:
                config_dict[name] = value
        return config_dict
    except ET.ParseError:
        print("Error: Failed to parse XML file.")
        sys.exit(1)
    except FileNotFoundError:
        print("Error: XML file not found.")
        sys.exit(1)

def apply_overrides(config_dict, overrides):
    for override in overrides:
        if '=' not in override:
            print(f"Error: Invalid override format: {override}")
            continue
        name, value = override.split('=', 1)
        config_dict[name] = value
    return config_dict

def is_valid_path(file_path):
    return os.path.isfile(file_path) and os.path.abspath(file_path).startswith(os.getcwd())

def main():
    if len(sys.argv) < 3:
        print("Usage: python config_resolver.py path/to/config.xml key1=value1 key2=value2 ...")
        sys.exit(1)

    xml_file_path = sys.argv[1]
    overrides = sys.argv[2:]

    if not is_valid_path(xml_file_path):
        print("Error: Invalid file path.")
        sys.exit(1)

    config_dict = parse_xml(xml_file_path)
    resolved_config = apply_overrides(config_dict, overrides)

    try:
        print(json.dumps(resolved_config, ensure_ascii=True))
    except TypeError:
        print("Error: Failed to serialize configuration to JSON.")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import json
import hashlib
from datetime import datetime
from html import escape

def load_products(json_path):
    with open(json_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    return data['products']

def save_cache(cache_path, products):
    with open(cache_path, 'w', encoding='utf-8') as f:
        json.dump(products, f)

def load_cache(cache_path):
    with open(cache_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def get_products(json_path, cache_path):
    if not os.path.exists(cache_path) or os.path.getmtime(json_path) > os.path.getmtime(cache_path):
        products = load_products(json_path)
        save_cache(cache_path, products)
    else:
        products = load_cache(cache_path)
    return products

def render_items(products):
    items = []
    for product in products:
        item = f'<li><strong>{escape(product["name"])}</strong> ${product["price"]:.2f}: {escape(product["description"])}</li>'
        items.append(item)
    return '<ul>\n  ' + '\n  '.join(items) + '\n</ul>'

def render_template(template_path, title, items):
    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()
    return template.replace('{{TITLE}}', escape(title)).replace('{{ITEMS}}', items)

def validate_file_path(base_path, file_path):
    abs_base_path = os.path.abspath(base_path)
    abs_file_path = os.path.abspath(file_path)
    if not abs_file_path.startswith(abs_base_path):
        raise ValueError("Invalid file path")

def main():
    if len(sys.argv) != 3:
        print("Usage: python catalog_renderer.py <json_file> <template_file>")
        sys.exit(1)

    json_path = sys.argv[1]
    template_path = sys.argv[2]
    base_dir = os.path.dirname(json_path)
    cache_path = os.path.join(base_dir, os.path.splitext(os.path.basename(json_path))[0] + '.cache')

    try:
        validate_file_path(base_dir, json_path)
        validate_file_path(base_dir, template_path)
    except ValueError as e:
        print(f"Error: {e}")
        sys.exit(1)

    try:
        products = get_products(json_path, cache_path)
        items_html = render_items(products)
        output_html = render_template(template_path, "Product Catalog", items_html)
        print(output_html)
    except Exception as e:
        print(f"Error processing files: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import requests
import html

def fetch_github_data(username):
    try:
        user_response = requests.get(f"https://api.github.com/users/{username}", timeout=10)
        if user_response.status_code != 200:
            print(f"ERROR: Failed to fetch user data", file=sys.stderr)
            sys.exit(1)
        user_data = user_response.json()

        repos_response = requests.get(f"https://api.github.com/users/{username}/repos", timeout=10)
        if repos_response.status_code != 200:
            print(f"ERROR: Failed to fetch repositories data", file=sys.stderr)
            sys.exit(1)
        repos_data = repos_response.json()

        return user_data, repos_data

    except requests.exceptions.RequestException as e:
        print(f"ERROR: {e}", file=sys.stderr)
        sys.exit(1)

def generate_html(user_data, repos_data):
    html_content = f"""
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>GitHub Report: {html.escape(user_data['login'])} </title>
        <style>
            body {{
                font-family: Arial, sans-serif;
            }}
            ul {{
                list-style-type: none;
                padding: 0;
            }}
            li {{
                border: 1px solid #ccc;
                margin: 5px 0;
                padding: 10px;
            }}
        </style>
    </head>
    <body>
        <h1>{html.escape(user_data['login'])}</h1>
        {f"<h2>{html.escape(user_data['name'])}</h2>" if user_data['name'] else ""}
        {f"<p>{html.escape(user_data['bio'])}</p>" if user_data['bio'] else ""}
        <img src="{user_data['avatar_url']}" alt="{html.escape(user_data['login'])}'s avatar" width="100">
        <h2>Public Repositories</h2>
        <ul>
    """
    for repo in repos_data:
        html_content += f"""
            <li>
                <a href="{html.escape(repo['html_url'])}">{html.escape(repo['name'])}</a> - 
                Stars: {repo['stargazers_count']}
            </li>
        """
    html_content += """
        </ul>
    </body>
    </html>
    """
    return html_content

def main():
    if len(sys.argv) != 2:
        print("Usage: python github_report.py <username>", file=sys.stderr)
        sys.exit(1)

    username = sys.argv[1]
    user_data, repos_data = fetch_github_data(username)
    html_output = generate_html(user_data, repos_data)
    print(html_output)

if __name__ == "__main__":
    main()

import sys
import json
import logging
import requests
from urllib.parse import urlparse, urlencode
from requests.exceptions import RequestException, Timeout

def setup_logging():
    logging.basicConfig(filename='endpoint_monitor.log', level=logging.INFO,
                        format='%(asctime)s - %(message)s')

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def load_config(file_path):
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {file_path}")
        sys.exit(1)
    except json.JSONDecodeError:
        logging.error(f"Configuration file is not valid JSON: {file_path}")
        sys.exit(1)
    except Exception as e:
        logging.error(f"Failed to read or parse config file: {e}")
        sys.exit(1)

def check_endpoint(endpoint):
    name = endpoint['name']
    url = endpoint['url']
    if not is_valid_url(url):
        logging.error(f"Invalid URL for endpoint {name}: {url}")
        return 'FAIL'

    try:
        response = requests.get(url, timeout=5, verify=True)
        status_code = response.status_code
        if 200 <= status_code <= 299:
            logging.info(f"Endpoint {name} is healthy with status code {status_code}")
            return 'OK'
        else:
            logging.warning(f"Endpoint {name} is unhealthy with status code {status_code}")
            return 'FAIL'
    except Timeout:
        logging.error(f"Timeout while checking endpoint {name}: {url}")
        return 'FAIL'
    except RequestException as e:
        logging.error(f"Error checking endpoint {name}: {e}")
        return 'FAIL'

def main():
    if len(sys.argv) != 2:
        logging.error("Usage: python endpoint_monitor.py path/to/config.json")
        sys.exit(1)

    setup_logging()
