import sys
import os
import json
import ast

OPERATIONS = [
    {
        "name": "sum",
        "required_role": "math",
        "expression": "x + y",
    },
    {
        "name": "greet",
        "required_role": "reports",
        "expression": "f\"Hello, {user}! You sent {msg}.\"",
    },
]

def is_safe_expression(expression):
    try:
        tree = ast.parse(expression, mode='eval')
        for node in ast.walk(tree):
            if not isinstance(node, (ast.Expression, ast.Str, ast.Num, ast.Name, ast.Load, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.JoinedStr, ast.FormattedValue)):
                return False
        return True
    except SyntaxError:
        return False

def safe_eval(expression, context):
    if not is_safe_expression(expression):
        raise ValueError("Unsafe expression")
    return eval(expression, {"__builtins__": {}}, context)

def main():
    if len(sys.argv) != 2:
        print("ERROR: unknown operation")
        return

    operation_name = sys.argv[1]
    operation = next((op for op in OPERATIONS if op["name"] == operation_name), None)

    if not operation:
        print("ERROR: unknown operation")
        return

    token = os.getenv("APP_TOKEN")
    try:
        token_data = json.loads(token)
        if "user" not in token_data or "roles" not in token_data:
            raise ValueError
    except (TypeError, ValueError, json.JSONDecodeError):
        print("ERROR: invalid token")
        return

    user = token_data["user"]
    roles = token_data["roles"]

    if operation["required_role"] not in roles:
        print("ERROR: forbidden")
        return

    try:
        input_data = json.loads(sys.stdin.readline().strip())
    except json.JSONDecodeError:
        print("ERROR: invalid input")
        return

    try:
        result = safe_eval(operation["expression"], {**input_data, "user": user})
        print(json.dumps({"operation": operation_name, "user": user, "result": result}))
    except Exception as e:
        print(f"ERROR: {str(e)}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import hashlib
import json
import os
import re

def generate_token(service, key, secret):
    combined = f"{service}:{key}:{secret}".encode('utf-8')
    hash_object = hashlib.sha256(combined)
    return re.sub(r'[^0-9a-f]', '', hash_object.hexdigest())[:32]

def is_valid_path(path):
    return os.path.abspath(path).startswith(os.getcwd())

def main():
    if len(sys.argv) != 3:
        print("Usage: python anonymize_keys.py CONFIG_XML_PATH SECRET_STRING")
        sys.exit(1)

    config_path = sys.argv[1]
    secret_string = sys.argv[2]

    if not is_valid_path(config_path):
        print("Error: Invalid file path")
        sys.exit(1)

    if not secret_string:
        print("Error: SECRET_STRING cannot be empty")
        sys.exit(1)

    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except ET.ParseError:
        print("Error: Invalid XML file")
        sys.exit(1)
    except FileNotFoundError:
        print("Error: XML file not found")
        sys.exit(1)

    tokens = {}
    for key_elem in root.findall('key'):
        service = key_elem.get('service')
        key = key_elem.text
        if service and key:
            token = generate_token(service, key, secret_string)
            tokens[service] = token

    print(json.dumps(tokens))

