import sys
import xml.etree.ElementTree as ET
import json
import ast
import operator

class SafeEval:
    def __init__(self, context):
        self.context = context
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.Pow: operator.pow,
            ast.BitXor: operator.xor,
            ast.USub: operator.neg
        }

    def eval_expr(self, expr):
        try:
            tree = ast.parse(expr, mode='eval')
            return self._eval(tree.body)
        except Exception:
            return None

    def _eval(self, node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = self._eval(node.left)
            right = self._eval(node.right)
            op = self.operators[type(node.op)]
            return op(left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = self._eval(node.operand)
            op = self.operators[type(node.op)]
            return op(operand)
        elif isinstance(node, ast.Name):
            if node.id in self.context:
                return self.context[node.id]
            else:
                raise NameError(f"Name '{node.id}' is not defined")
        else:
            raise TypeError(f"Unsupported operation: {ast.dump(node)}")

def main():
    if len(sys.argv) != 3:
        print("Usage: python apply_xml_calculations.py <xml_file> <json_file>")
        sys.exit(1)

    xml_file = sys.argv[1]
    json_file = sys.argv[2]

    try:
        with open(json_file, 'r') as f:
            data = json.load(f)
    except json.JSONDecodeError:
        print(f"Error: JSON file '{json_file}' is not valid JSON", file=sys.stderr)
        sys.exit(1)
    except IOError:
        print(f"Error: Cannot read JSON file '{json_file}'", file=sys.stderr)
        sys.exit(1)

    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError:
        print(f"Error: XML file '{xml_file}' is not well-formed", file=sys.stderr)
        sys.exit(1)
    except IOError:
        print(f"Error: Cannot read XML file '{xml_file}'", file=sys.stderr)
        sys.exit(1)

    safe_eval = SafeEval(data)

    for calc in root.findall('calc'):
        name = calc.get('name')
        expr = calc.get('expr')
        result = safe_eval.eval_expr(expr)
        if result is not None:
            data[name] = result
        else:
            print(f"ERROR name={name} expr={expr}", file=sys.stderr)

    print(json.dumps(data))

if __name__ == "__main__":
    main()

import sys
import re
import json
import ast
import operator

def render_page(template_path, json_path):
    try:
        with open(template_path, 'r') as template_file:
            template = template_file.read()

        with open(json_path, 'r') as json_file:
            context = json.load(json_file)
    except (IOError, json.JSONDecodeError) as e:
        print(f"Error reading files: {e}")
        sys.exit(1)

    def replace_variable(match):
        key = match.group(1)
        if not key.isidentifier():
            return ''
        return str(context.get(key, ''))

    def safe_eval(node, context):
        if isinstance(node, ast.Expression):
            return safe_eval(node.body, context)
        elif isinstance(node, ast.BinOp):
            left = safe_eval(node.left, context)
            right = safe_eval(node.right, context)
            op = {
                ast.Add: operator.add,
                ast.Sub: operator.sub,
                ast.Mult: operator.mul,
                ast.Div: operator.truediv,
                ast.FloorDiv: operator.floordiv,
                ast.Mod: operator.mod,
                ast.Pow: operator.pow
            }.get(type(node.op))
            if op:
                return op(left, right)
        elif isinstance(node, ast.Name):
            if node.id in context:
                return context[node.id]
        elif isinstance(node, ast.Str):
            return node.s
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.UnaryOp):
            operand = safe_eval(node.operand, context)
            if isinstance(node.op, ast.UAdd):
                return +operand
            elif isinstance(node.op, ast.USub):
                return -operand
        return ''

    def replace_expression(match):
        expression = match.group(1)
        try:
            tree = ast.parse(expression, mode='eval')
            return str(safe_eval(tree.body, context))
        except (SyntaxError, TypeError):
            return ''

    template = re.sub(r'{{(\w+)}}', replace_variable, template)
    template = re.sub(r'{{=\s*(.*?)\s*}}', replace_expression, template)

    print(template)

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python render_page.py <template_path> <json_path>")
        sys.exit(1)
    render_page(sys.argv[1], sys.argv[2])

import sys
import json
import os
import requests
import subprocess
import shlex
import time
import logging

def load_cache(cache_file):
    try:
        if os.path.exists(cache_file):
            with open(cache_file, 'r') as f:
                return json.load(f)
    except (IOError, json.JSONDecodeError) as e:
        logging.error(f"Error loading cache: {e}")
    return {}

def save_cache(cache_file, cache):
    try:
        with open(cache_file, 'w') as f:
            json.dump(cache, f)
    except IOError as e:
        logging.error(f"Error saving cache: {e}")

def validate_config(config):
    if not isinstance(config, list):
        raise ValueError("Configuration must be a list of objects")
    for item in config:
        if not isinstance(item, dict):
            raise ValueError("Each configuration item must be a dictionary")
        if 'name' not in item or 'url' not in item or 'on_change_command' not in item:
            raise ValueError("Each item must contain 'name', 'url', and 'on_change_command'")
        if not isinstance(item['name'], str) or not isinstance(item['url'], str) or not isinstance(item['on_change_command'], str):
            raise ValueError("'name', 'url', and 'on_change_command' must be strings")

def main():
    logging.basicConfig(level=logging.INFO)

    if len(sys.argv) != 2:
        print("Usage: python watch_endpoints.py <config_file>")
        sys.exit(1)

    config_file = sys.argv[1]
    cache_file = 'status_cache.json'

    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        validate_config(config)
    except (IOError, json.JSONDecodeError, ValueError) as e:
        logging.error(f"Error reading or validating config file: {e}")
        sys.exit(1)

    cache = load_cache(cache_file)

    for item in config:
        name = item['name']
        url = item['url']
        on_change_command = item['on_change_command']

        try:
            response = requests.get(url, timeout=5)
            current_status = response.status_code
        except requests.RequestException as e:
            logging.warning(f"Request to {url} failed: {e}")
            current_status = None

        previous_status = cache.get(name)

        if previous_status is None or current_status != previous_status:
            if previous_status is not None:
                print(f"CHANGED {name} {previous_status} -> {current_status}")
            else:
                print(f"SAME {name} {current_status}")

            if current_status is not None:
                cache[name] = current_status
                try:
                    result = subprocess.run(shlex.split(on_change_command), check=True)
                    print(f"COMMAND_EXIT {name} {result.returncode}")
                except subprocess.CalledProcessError as e:
                    logging.error(f"Command for {name} failed with exit code {e.returncode}")
                    print(f"COMMAND_EXIT {name} {e.returncode}")

        time.sleep(1)  # Rate limiting

    save_cache(cache_file, cache)

if __name__ == "__main__":
    main()

import sys
