def validate_xml_structure(root):
    if root.tag != 'checks':
        raise ValueError("Invalid XML structure: root element must be 'checks'")
    for check in root.findall('check'):
        if 'name' not in check.attrib or 'url' not in check.attrib:
            raise ValueError("Invalid XML structure: 'check' element must have 'name' and 'url' attributes")

def main():
    logging.basicConfig(level=logging.INFO)
    config_path = sys.argv[1]

    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
