    except ET.ParseError as e:
        logging.error(f"XML parsing error: {e}")
        return
    except ValueError as e:
        logging.error(e)
        return

    for check in root.findall('check'):
        name = check.get('name')
        url = check.get('url')
        on_fail = check.find('on_fail')

        try:
