import sys
import subprocess
import json
import hmac
import hashlib
import requests
from datetime import datetime, timezone
from urllib.parse import urlparse
import signal

def validate_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def run_command(command, timeout=60):
    try:
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, preexec_fn=os.setsid)
        stdout, stderr = process.communicate(timeout=timeout)
        exit_code = process.returncode
    except subprocess.TimeoutExpired:
        os.killpg(process.pid, signal.SIGTERM)
        stdout, stderr = b'', b''
        exit_code = -1
    except Exception as e:
        stdout, stderr = b'', str(e).encode('utf-8')
        exit_code = -1
    return exit_code, stdout.decode('utf-8'), stderr.decode('utf-8')

def main():
    if len(sys.argv) != 4:
        print("Usage: python report_runner.py <command> <endpoint_url> <secret_key>")
        sys.exit(1)

    command = sys.argv[1]
    endpoint_url = sys.argv[2]
    secret_key = sys.argv[3]

    if not validate_url(endpoint_url):
        print("Invalid endpoint URL.")
        sys.exit(1)

    exit_code, stdout, stderr = run_command(command)

    timestamp = datetime.now(timezone.utc).isoformat().replace('+00:00', 'Z')

    payload = {
        "timestamp": timestamp,
        "command": command,
        "exit_code": exit_code,
        "stdout": stdout,
        "stderr": stderr
    }
    payload_json = json.dumps(payload)

    mac = hmac.new(secret_key.encode('utf-8'), payload_json.encode('utf-8'), hashlib.sha256).hexdigest()

    headers = {
        'Content-Type': 'application/json',
        'X-Signature': mac
    }

    try:
        response = requests.post(endpoint_url, data=payload_json, headers=headers, verify=True)
    except requests.RequestException as e:
        print(f"HTTP request failed: {e}")
        sys.exit(1)

    print(f"HTTP_STATUS: {response.status_code}")
    print(f"RESPONSE_HEADERS: {'; '.join(f'{k}: {v}' for k, v in response.headers.items())}")
    print(f"RESPONSE_BODY: {response.text[:100]}...")  # Limit output for security

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import requests
from html import escape
from requests.adapters import HTTPAdapter
from requests.packages.urllib3.util.retry import Retry

def validate_service(service):
    required_keys = {'name', 'url', 'check_command'}
    if not all(k in service for k in required_keys):
        raise ValueError("Missing required keys in service descriptor")

def sanitize_html(text):
    return escape(text)

def run_command_safely(command):
    try:
        result = subprocess.run(command, shell=False, check=False, capture_output=True, text=True)
        return result.returncode
    except Exception as e:
        sys.stderr.write(f"Error running command: {e}\n")
        return "N/A"

def get_http_status(url):
    try:
        session = requests.Session()
        retries = Retry(total=3, backoff_factor=0.3, status_forcelist=[500, 502, 503, 504])
        session.mount('http://', HTTPAdapter(max_retries=retries))
        session.mount('https://', HTTPAdapter(max_retries=retries))
        response = session.get(url, timeout=10, verify=True)
        return response.status_code
    except requests.RequestException:
        return "N/A"

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python service_report.py <config_file>\n")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as file:
            config = json.load(file)
    except (IOError, json.JSONDecodeError) as e:
        sys.stderr.write(f"Error reading or parsing config file: {e}\n")
        sys.exit(1)

    if 'services' not in config or not isinstance(config['services'], list):
        sys.stderr.write("Error: 'services' key is missing or not a list\n")
        sys.exit(1)

    services = config['services']
    for service in services:
        try:
            validate_service(service)
        except ValueError as e:
            sys.stderr.write(f"Error: {e}\n")
            sys.exit(1)

    print("<html><head><title>Service Status Report</title></head><body>")
    print("<h1>Service Status Report</h1>")
    print("<table><tr><th>Name</th><th>URL</th><th>Command Exit Code</th><th>HTTP Status</th></tr>")

    for service in services:
        name = sanitize_html(service['name'])
        url = sanitize_html(service['url'])
        check_command = service['check_command'].split()

        command_exit_code = run_command_safely(check_command)
        http_status = get_http_status(url)

        print(f"<tr><td>{name}</td><td>{url}</td><td>{command_exit_code}</td><td>{http_status}</td></tr>")

    print("</table></body></html>")

if __name__ == "__main__":
    main()

import sys
import json
import subprocess
import urllib.request
import urllib.parse
import re
import time

def is_valid_url(url):
    parsed = urllib.parse.urlparse(url)
    return parsed.scheme in ('http', 'https')

def is_safe_command(command):
    # Basic command safety check: no shell metacharacters
    unsafe_chars = re.compile(r'[;&|`$]')
    return not unsafe_chars.search(command)

def is_safe_transform(transform):
    # Basic transform safety check: no dangerous built-ins or functions
    unsafe_functions = re.compile(r'\b(exec|eval|open|__import__|input|os|sys|subprocess)\b')
    return not unsafe_functions.search(transform)

def main():
    if len(sys.argv) != 2:
        print("ERROR")
        return

    url = sys.argv[1]
    if not is_valid_url(url):
        print("ERROR")
        return

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            tasks = json.loads(response.read().decode('utf-8'))
    except Exception:
        print("ERROR")
        return

    if not isinstance(tasks, list):
        print("ERROR")
        return

    for task in tasks:
        if not isinstance(task, dict) or not all(k in task for k in ("name", "command", "transform")):
            print("ERROR")
            return

        name = task["name"]
        command = task["command"]
        transform = task["transform"]

        if not is_safe_command(command) or not is_safe_transform(transform):
            print("ERROR")
            return

        try:
            result = subprocess.run(command, shell=False, check=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=30)
            output = result.stdout.decode('utf-8')
            transformed_result = eval(transform, {"output": output, "__builtins__": {}})
            print(f"TASK {name}")
            print(f"RESULT {str(transformed_result)}")
        except subprocess.TimeoutExpired:
            print("ERROR")
            return
        except Exception:
            print("ERROR")
            return

if __name__ == "__main__":
    main()

import os
import sys
import hashlib
import re
import subprocess

def evaluate_condition(condition, run_level):
    # Use a safer evaluation method by restricting the allowed operations
    allowed_names = {"RUN_LEVEL": run_level}
    code = compile(condition, "<string>", "eval")
    for name in code.co_names:
        if name not in allowed_names:
            raise ValueError(f"Use of name '{name}' is not allowed")
    return eval(code, {"__builtins__": {}}, allowed_names)

def sanitize_command(command):
    # Basic sanitation to prevent shell injection
    if not re.match(r'^[a-zA-Z0-9\s\.\-_/]+$', command):
        raise ValueError("Invalid command")
    return command

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <config_path>")
        sys.exit(1)

    config_path = sys.argv[1]
    run_level = int(os.getenv("RUN_LEVEL", 0))

    try:
        with open(config_path, "r", encoding="utf-8") as file:
            for line in file:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue

                parts = line.split("\t")
                if len(parts) != 3:
                    print(f"INVALID_LINE\t{line}")
                    continue

                command, condition, expected_digest = parts
                try:
                    command = sanitize_command(command)
                    condition_value = evaluate_condition(condition, run_level)
                except Exception as e:
                    print(f"ERROR\t{command}\t{str(e)}")
                    continue

                if condition_value == 0:
                    print(f"SKIP\t{command}")
                else:
                    try:
                        result = subprocess.run(command, shell=True, check=True, capture_output=True, text=True)
                        actual_digest = hashlib.sha3_256(result.stdout.encode("utf-8")).hexdigest()

                        if actual_digest == expected_digest:
                            print(f"OK\t{command}")
                        else:
                            print(f"MISMATCH\t{command}")
                    except subprocess.CalledProcessError as e:
                        print(f"ERROR\t{command}\t{e}")
                    except Exception as e:
                        print(f"ERROR\t{command}\t{str(e)}")

    except FileNotFoundError:
        print(f"ERROR\tFile not found: {config_path}")
    except Exception as e:
        print(f"ERROR\tGeneral error: {str(e)}")

if __name__ == "__main__":
    main()

import xml.etree.ElementTree as ET
import re
import os
import ast
import math

def parse_xml_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    variables = {}
    for var in root.findall('variable'):
        name = var.get('name')
        value = float(var.get('value'))
        variables[name] = value
    return variables

def safe_eval(expr, variables):
    allowed_operators = {
        ast.Add: lambda x, y: x + y,
        ast.Sub: lambda x, y: x - y,
        ast.Mult: lambda x, y: x * y,
        ast.Div: lambda x, y: x / y,
        ast.Pow: lambda x, y: x ** y,
        ast.USub: lambda x: -x,
        ast.Num: lambda x: x.n,
        ast.Name: lambda x: variables.get(x.id, 0)
    }

    def eval_node(node):
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            return allowed_operators[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            return allowed_operators[type(node.op)](operand)
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            return variables.get(node.id, 0)
        else:
            raise ValueError("Unsupported operation")

    try:
        tree = ast.parse(expr, mode='eval')
        return eval_node(tree.body)
    except Exception as e:
        return f"Error evaluating expression: {e}"

def evaluate_expression(expr, variables):
    try:
        return str(safe_eval(expr, variables))
    except Exception as e:
        return f"Error evaluating expression: {e}"

def process_template(template, variables):
    pattern = r'\{\{([^{}]+)\}\}'
    return re.sub(pattern, lambda m: evaluate_expression(m.group(1), variables), template)

def validate_file_path(path):
    if not os.path.isabs(path):
        raise ValueError("File path must be absolute")
    if not os.path.exists(os.path.dirname(path)):
        raise ValueError("Directory does not exist")

def main():
    config_path = input("Enter config XML path: ")
    template_path = input("Enter template path: ")
    output_path = input("Enter output path: ")

    try:
        validate_file_path(config_path)
        validate_file_path(template_path)
        validate_file_path(output_path)
    except ValueError as e:
        print(f"Invalid file path: {e}")
        return

    try:
        variables = parse_xml_config(config_path)
    except ET.ParseError:
        print("Error parsing XML configuration")
        return

    try:
        with open(template_path, 'r') as template_file:
            template = template_file.read()
    except IOError:
        print("Error reading template file")
        return

    processed_report = process_template(template, variables)

    try:
        with open(output_path, 'w') as output_file:
            output_file.write(processed_report)
    except IOError:
        print("Error writing output file")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import os

def parse_config(config_path):
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
        max_total_bytes = int(root.find('maxTotalBytes').text)
        if max_total_bytes < 0:
            raise ValueError("maxTotalBytes must be non-negative")
        return max_total_bytes
    except ET.ParseError as e:
        raise ValueError(f"Error parsing XML: {e}")
    except Exception as e:
        raise ValueError(f"Error reading config file: {e}")

def sanitize_path(path):
    return os.path.normpath(os.path.abspath(path))

def read_workload(workload_path):
    try:
        with open(workload_path, 'r') as workload_file:
            return workload_file.readlines()
    except Exception as e:
        raise ValueError(f"Error reading workload file: {e}")

def process_instructions(instructions, max_total_bytes):
    user_allocations = {}
    total_allocated_bytes = 0

    for instruction in instructions:
        parts = instruction.strip().split()
        if len(parts) != 3 or parts[0] != 'ALLOCATE':
            continue

        user_id = parts[1]
        try:
            requested_bytes = int(parts[2])
            if requested_bytes < 0:
                raise ValueError("Requested bytes must be non-negative")
        except ValueError:
            continue

        if requested_bytes + total_allocated_bytes > max_total_bytes:
            print(f"THROTTLED {user_id} {requested_bytes}")
        else:
            if user_id not in user_allocations:
                user_allocations[user_id] = 0
            user_allocations[user_id] += requested_bytes
            total_allocated_bytes += requested_bytes
            print(f"ALLOCATED {user_id} {requested_bytes}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python allocator.py CONFIG_PATH")
        return

    config_path = sys.argv[1]
    try:
        max_total_bytes = parse_config(config_path)
    except ValueError as e:
        print(f"Error: {e}")
        return

    workload_path = input().strip()
    try:
        workload_path = sanitize_path(workload_path)
        if not os.path.isfile(workload_path):
            raise ValueError("Invalid workload file path")
        instructions = read_workload(workload_path)
    except ValueError as e:
        print(f"Error: {e}")
        return

    process_instructions(instructions, max_total_bytes)

if __name__ == "__main__":
    main()

import sys
import csv
import xml.etree.ElementTree as ET
import sqlite3
import re
import os

def load_configuration():
    tree = ET.parse('reports.xml')
    root = tree.getroot()
    reports = {}
    for report in root.findall('report'):
        reports[report.get('id')] = {
            'queryTemplate': report.get('queryTemplate'),
            'requiredRole': report.get('requiredRole')
        }
    return reports

def load_tokens():
    tokens = {}
    with open('tokens.csv', newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            tokens[row['token']] = {
                'userId': row['userId'],
                'role': row['role']
            }
    return tokens

def validate_date(date):
    return re.match(r'^\d{4}-\d{2}-\d{2}$', date) is not None

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    token = sys.argv[1]
    report_id = sys.argv[2]

    reports = load_configuration()
    tokens = load_tokens()

    if token not in tokens:
        print("INVALID TOKEN")
        sys.exit(1)

    user_info = tokens[token]
    if report_id not in reports:
        print("UNKNOWN REPORT")
        sys.exit(3)

    report = reports[report_id]
    if user_info['role'] != report['requiredRole']:
        print("FORBIDDEN")
