import sys
import xml.etree.ElementTree as ET
import sqlite3
from datetime import datetime, timedelta
import time
import os
import re

def parse_config(config_path):
    # Prevent XXE by disabling external entity loading
    parser = ET.XMLParser(resolve_entities=False)
    tree = ET.parse(config_path, parser=parser)
    root = tree.getroot()
    db_path = root.find('database/path').text
    return db_path, root.findall('report')

def find_report(reports, report_name):
    for report in reports:
        if report.get('name') == report_name:
            return report
    return None

def validate_date(date_text):
    try:
        return datetime.strptime(date_text, '%Y-%m-%d')
    except ValueError:
        raise ValueError("Incorrect date format, should be YYYY-MM-DD")

def sanitize_path(path):
    # Prevent path traversal by ensuring the path is within a specific directory
    base_dir = os.path.abspath(os.path.dirname(__file__))
    full_path = os.path.abspath(path)
    if not full_path.startswith(base_dir):
        raise ValueError("Invalid path: Attempted path traversal")
    return full_path

def generate_dates(start_date, end_date):
    current_date = start_date
    while current_date <= end_date:
        yield current_date.strftime('%Y-%m-%d')
        current_date += timedelta(days=1)

def main():
    if len(sys.argv) != 5:
        print("Usage: python report_runner.py CONFIG_PATH REPORT_NAME START_DATE END_DATE", file=sys.stderr)
        sys.exit(1)

    config_path, report_name, start_date_str, end_date_str = sys.argv[1:]

    try:
        start_date = validate_date(start_date_str)
        end_date = validate_date(end_date_str)
    except ValueError as e:
        print(str(e), file=sys.stderr)
        sys.exit(1)

    try:
        db_path, reports = parse_config(config_path)
        db_path = sanitize_path(db_path)
    except ET.ParseError:
        print("Error parsing XML configuration", file=sys.stderr)
        sys.exit(1)
    except ValueError as e:
        print(str(e), file=sys.stderr)
        sys.exit(1)

    report = find_report(reports, report_name)

    if report is None:
        print(f"Report '{report_name}' not found", file=sys.stderr)
        sys.exit(1)

    try:
        max_per_minute = int(report.get('max_per_minute'))
        if max_per_minute <= 0:
            raise ValueError("max_per_minute must be greater than 0")
    except ValueError as e:
        print(str(e), file=sys.stderr)
        sys.exit(1)

    sql_template = report.find('sql').text

    try:
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            delay = 60.0 / max_per_minute

            for date in generate_dates(start_date, end_date):
                # Use parameterized queries to prevent SQL injection
                sql_query = re.sub(r'\{date\}', '?', sql_template)
                cursor.execute(sql_query, (date,))

                for row in cursor.fetchall():
                    print(','.join(map(str, row)))

                if date != end_date.strftime('%Y-%m-%d'):
                    time.sleep(delay)
    except sqlite3.Error as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import os
import urllib.request
import ssl
import html
from urllib.parse import urlparse

def load_config(config_path):
    if not os.path.isfile(config_path):
        raise ValueError("Invalid configuration file path.")
    with open(config_path, 'r', encoding='utf-8') as file:
        config = json.load(file)
    if 'api_url' not in config or 'page_title' not in config:
        raise ValueError("Configuration must contain 'api_url' and 'page_title'.")
    return config

def fetch_articles(api_url):
    if not urlparse(api_url).scheme == 'https':
        raise ValueError("API URL must use HTTPS.")
    context = ssl.create_default_context()
    try:
        with urllib.request.urlopen(api_url, context=context) as response:
            if response.getheader('Content-Type') != 'application/json':
                raise ValueError("Unexpected Content-Type.")
            return json.load(response)
    except (urllib.error.URLError, json.JSONDecodeError, ValueError) as e:
        return None

def load_cache():
    cache_path = os.path.join(os.getcwd(), 'news_cache.json')
    if os.path.exists(cache_path):
        with open(cache_path, 'r', encoding='utf-8') as file:
            return json.load(file)
    return []

def save_cache(articles):
    cache_path = os.path.join(os.getcwd(), 'news_cache.json')
    with open(cache_path, 'w', encoding='utf-8') as file:
        json.dump(articles, file)

def sanitize_html(text):
    return html.escape(text)

def generate_html(articles, page_title):
    print("<!DOCTYPE html>")
    print("<html>")
    print("<head>")
    print(f"    <title>{sanitize_html(page_title)}</title>")
    print("</head>")
    print("<body>")
    print(f"    <h1>{sanitize_html(page_title)}</h1>")
    print("    <ul>")
    for article in articles:
        print(f"        <li><a href=\"{sanitize_html(article['url'])}\">{sanitize_html(article['title'])}</a></li>")
    print("    </ul>")
    print("</body>")
    print("</html>")

def main(config_path):
    try:
        config = load_config(config_path)
        api_url = config['api_url']
        page_title = config['page_title']

        articles = fetch_articles(api_url)
        if articles is None:
            articles = load_cache()

        save_cache(articles)
        generate_html(articles, page_title)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python news_page.py CONFIG_PATH", file=sys.stderr)
        sys.exit(1)
    main(sys.argv[1])

import sys
import os
import json
import urllib.request
import ssl
import time
from urllib.error import URLError, HTTPError

def fetch_data(url):
    context = ssl.create_default_context()
    try:
        with urllib.request.urlopen(url, context=context) as response:
            return response.read().decode('utf-8')
    except (URLError, HTTPError) as e:
        print(f"Error fetching data: {e.reason}", file=sys.stderr)
        sys.exit(1)

def load_cache():
    if os.path.exists('.remote_eval_cache'):
        try:
            with open('.remote_eval_cache', 'r') as cache_file:
                return [json.loads(line) for line in cache_file if line.strip()]
        except (IOError, json.JSONDecodeError) as e:
            print(f"Error loading cache: {e}", file=sys.stderr)
            sys.exit(1)
    return None

def save_cache(data):
    try:
        with open('.remote_eval_cache', 'w') as cache_file:
            for record in data:
                cache_file.write(json.dumps(record) + '\n')
    except IOError as e:
        print(f"Error saving cache: {e}", file=sys.stderr)
        sys.exit(1)

def validate_record(record):
    if not isinstance(record, dict):
        return False
    if 'id' not in record or 'expression' not in record or 'x' not in record:
        return False
    if not isinstance(record['id'], str) or not isinstance(record['expression'], str):
        return False
    if not isinstance(record['x'], (int, float)):
        return False
    return True

def main():
    if len(sys.argv) < 2:
        print("Usage: python remote_eval.py <DATA_URL> [--use-cache]")
        sys.exit(1)

    data_url = sys.argv[1]
    use_cache = '--use-cache' in sys.argv

    records = None
    if use_cache:
        records = load_cache()

    if records is None:
        data = fetch_data(data_url)
        records = [json.loads(line) for line in data.splitlines() if line.strip()]
        records = [record for record in records if validate_record(record)]
        save_cache(records)

    for record in records:
        x = record['x']
        expression = record['expression']
        try:
            result = eval(expression, {'x': x, '__builtins__': {}})
        except Exception as e:
            print(f"Error evaluating expression for id {record['id']}: {e}", file=sys.stderr)
            result = None
        output_record = {
            'id': record['id'],
            'expression': record['expression'],
            'x': record['x'],
            'result': result
        }
        print(json.dumps(output_record))

if __name__ == '__main__':
    main()

import sys
import json
import os
import secrets
import hmac
import hashlib
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def generate_secure_token(username):
    # Use a secure random token generator
    return secrets.token_hex(16)

def validate_json(data, required_fields):
    if not isinstance(data, dict):
        return False
    for field in required_fields:
        if field not in data:
            return False
    return True

def login_mode():
    input_data = sys.stdin.readline().strip()
    try:
        data = json.loads(input_data)
    except json.JSONDecodeError:
        logging.error("Invalid JSON input")
        sys.exit(1)

    if not validate_json(data, ['accounts', 'username', 'password']):
        logging.error("Invalid input structure")
        sys.exit(1)

    username = data['username']
    password = data['password']
    accounts = data['accounts']

    for account in accounts:
        if account.get('username') == username and account.get('password') == password:
            token = generate_secure_token(username)
            output = json.dumps({'username': username, 'token': token})
            print(output)
            logging.info(f"User {username} logged in successfully")
            return

    print(json.dumps({"error": "invalid_credentials"}))
    logging.warning(f"Failed login attempt for user {username}")

def page_mode():
    sessions_input = sys.stdin.readline().strip()
    token_input = sys.stdin.readline().strip()
    try:
        sessions_data = json.loads(sessions_input)
        token_data = json.loads(token_input)
    except json.JSONDecodeError:
        logging.error("Invalid JSON input")
        sys.exit(1)

    if not validate_json(sessions_data, ['sessions']) or not validate_json(token_data, ['token']):
        logging.error("Invalid input structure")
        sys.exit(1)

    token = token_data['token']
    sessions = sessions_data['sessions']

    for session in sessions:
        if hmac.compare_digest(session.get('token'), token):
            username = session.get('username')
            try:
                with open('profile_template.html', 'r') as file:
                    template = file.read()
                output = template.replace('{{username}}', username).replace('{{token}}', token)
                print(output)
                logging.info(f"User {username} accessed page successfully")
            except FileNotFoundError:
                logging.error("Template file not found")
                sys.exit(1)
            return

    print("NO ACCESS")
    logging.warning(f"Unauthorized access attempt with token {token}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        logging.error("Invalid number of arguments")
        sys.exit(1)

    mode = sys.argv[1]
    if mode == 'login':
        login_mode()
    elif mode == 'page':
        page_mode()
    else:
        logging.error("Invalid mode")
        sys.exit(1)

import sys
import xml.etree.ElementTree as ET
import json
import os
import ast
import hashlib

def safe_eval(expr, variables):
    allowed_operators = {
        ast.Add: lambda x, y: x + y,
        ast.Sub: lambda x, y: x - y,
        ast.Mult: lambda x, y: x * y,
        ast.Div: lambda x, y: x / y,
        ast.Pow: lambda x, y: x ** y,
        ast.BitXor: lambda x, y: x ^ y,
        ast.USub: lambda x: -x
    }

    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            else:
                raise ValueError(f"Undefined variable: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](left, right)
            else:
                raise ValueError(f"Unsupported operation: {op_type}")
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](operand)
            else:
                raise ValueError(f"Unsupported operation: {op_type}")
        else:
            raise ValueError(f"Unsupported expression: {ast.dump(node)}")

    tree = ast.parse(expr, mode='eval')
    return eval_node(tree.body)

def validate_xml(tree):
    root = tree.getroot()
    if root.tag != 'calcflow':
        raise ValueError("Root element must be <calcflow>")
    for calculation in root.findall('calculation'):
        if 'name' not in calculation.attrib or 'expr' not in calculation.attrib:
            raise ValueError("Each <calculation> must have 'name' and 'expr' attributes")

def run_mode(config_path):
    tree = ET.parse(config_path)
    validate_xml(tree)

    input_data = json.load(sys.stdin)
    results = {}

    for calculation in tree.getroot().findall('calculation'):
        name = calculation.get('name')
        expr = calculation.get('expr')
        try:
            result = safe_eval(expr, input_data)
            if not isinstance(result, (int, float)):
                raise ValueError(f"Result of calculation '{name}' is not numeric")
            results[name] = result
        except Exception as e:
            print(f"Error evaluating calculation '{name}': {e}", file=sys.stderr)
            sys.exit(1)

    print(json.dumps(results))

    cache_data = {
        'results': results,
        'variables': input_data
    }

    cache_filename = 'calcflow.cache'
    with open(cache_filename, 'wb') as cache_file:
        cache_file.write(json.dumps(cache_data).encode('utf-8'))

def replay_mode(cache_path):
    if not os.path.exists(cache_path):
        print(f"Cache file not found: {cache_path}", file=sys.stderr)
        sys.exit(1)

    with open(cache_path, 'rb') as cache_file:
        cache_data = json.loads(cache_file.read().decode('utf-8'))

    results = cache_data['results']
    print(json.dumps(results))

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python calcflow.py <run|replay> <CONFIG_PATH|CACHE_PATH>")
        sys.exit(1)

    mode, path = sys.argv[1], sys.argv[2]

    if mode == 'run':
        run_mode(path)
    elif mode == 'replay':
        replay_mode(path)
    else:
        print("Invalid mode. Use 'run' or 'replay'.")
        sys.exit(1)

import sys
import xml.etree.ElementTree as ET
import pickle
import os
import logging
from xml.etree.ElementTree import ParseError

class Scheduler:
    def __init__(self, resources_file, state_file):
        self.resources = self.load_resources(resources_file)
        self.state = self.load_state(state_file)
        self.state_file = state_file

    def load_resources(self, resources_file):
        try:
            tree = ET.parse(resources_file)
            root = tree.getroot()
            resources = {}
            for resource in root.findall('resource'):
                name = resource.get('name')
                max_concurrent = int(resource.get('max_concurrent'))
                if not name or max_concurrent <= 0:
                    raise ValueError("Invalid resource configuration")
                resources[name] = {'max_concurrent': max_concurrent, 'running': [], 'queued': []}
            return resources
        except (FileNotFoundError, ParseError, ValueError) as e:
            logging.error(f"Error loading resources: {e}")
            sys.exit(1)

    def load_state(self, state_file):
        if not os.path.exists(state_file) or os.path.getsize(state_file) == 0:
            return {name: {'running': [], 'queued': []} for name in self.resources}
        try:
            with open(state_file, 'rb') as f:
                return pickle.load(f)
        except (FileNotFoundError, EOFError, pickle.UnpicklingError) as e:
            logging.error(f"Error loading state: {e}")
            return {name: {'running': [], 'queued': []} for name in self.resources}

    def save_state(self):
        try:
            with open(self.state_file, 'wb') as f:
                pickle.dump(self.state, f)
        except IOError as e:
            logging.error(f"Error saving state: {e}")

    def process_job(self, resource_name, job_id):
        if not resource_name or not job_id:
            logging.warning("Invalid job request")
            return

        resource = self.resources.get(resource_name)
        if not resource:
            logging.warning(f"Unknown resource: {resource_name}")
            return

        state = self.state[resource_name]
        if len(state['running']) < resource['max_concurrent']:
            state['running'].append(job_id)
            print(f"start {job_id} on {resource_name}")
        else:
            state['queued'].append(job_id)
            print(f"queue {job_id} on {resource_name}")

    def run(self):
        for line in sys.stdin:
            try:
                resource_name, job_id = line.strip().split()
                self.process_job(resource_name, job_id)
            except ValueError:
                logging.warning("Malformed job request")
        self.save_state()

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python scheduler.py resources.xml state.bin")
        sys.exit(1)

    resources_file = sys.argv[1]
    state_file = sys.argv[2]

    if not os.path.isfile(resources_file):
        print(f"Error: Resources file '{resources_file}' does not exist.")
        sys.exit(1)

    logging.basicConfig(level=logging.INFO)

    scheduler = Scheduler(resources_file, state_file)
    scheduler.run()

import os
import sys
import json
import pickle
import ast
import operator

class ExpressionEvaluator(ast.NodeVisitor):
    def __init__(self, n):
        self.n = n
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.USub: operator.neg
        }

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        return self.operators[type(node.op)](left, right)

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        return self.operators[type(node.op)](operand)

    def visit_Num(self, node):
        return node.n

    def visit_Name(self, node):
        if node.id == 'n':
            return self.n
        raise ValueError(f"Invalid variable: {node.id}")

    def visit_Expression(self, node):
        return self.visit(node.body)

    def evaluate(self, expr):
        try:
            tree = ast.parse(expr, mode='eval')
            return self.visit(tree.body)
        except Exception as e:
            raise ValueError(f"Invalid expression: {expr}") from e

def load_cache():
    cache_file = '.job_cache.bin'
    if os.path.exists(cache_file):
        with open(cache_file, 'rb') as f:
            return pickle.load(f)
    return {}

def save_cache(cache):
    with open('.job_cache.bin', 'wb') as f:
        pickle.dump(cache, f)

def validate_config(config):
    if not isinstance(config, dict):
        raise ValueError("Config must be a JSON object")
    if 'memory_budget' not in config or not isinstance(config['memory_budget'], int) or config['memory_budget'] < 0:
        raise ValueError("Invalid memory_budget")
    if 'jobs' not in config or not isinstance(config['jobs'], list):
        raise ValueError("Invalid jobs")
    for job in config['jobs']:
        if not isinstance(job, dict) or 'id' not in job or 'cost' not in job or 'expr' not in job:
            raise ValueError("Invalid job structure")
        if not isinstance(job['id'], str) or not job['id']:
            raise ValueError("Invalid job id")
        if not isinstance(job['cost'], int) or job['cost'] < 0:
            raise ValueError("Invalid job cost")
        if not isinstance(job['expr'], str):
            raise ValueError("Invalid job expr")

def main(config_path):
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
        validate_config(config)
    except Exception as e:
        print(f"Error reading or parsing config: {e}")
        sys.exit(1)

    memory_budget = config['memory_budget']
    jobs = config['jobs']

    try:
        n_value = os.getenv('N_VALUE', '1')
        n = int(n_value)
    except ValueError:
        print("Error: N_VALUE must be an integer")
        sys.exit(1)

    cache = load_cache()
    used_cost = 0
    evaluator = ExpressionEvaluator(n)

    for job in jobs:
        job_id = job['id']
        cost = job['cost']
        expr = job['expr']

        if used_cost + cost > memory_budget:
            print(f"SKIPPED {job_id}")
            continue

        if job_id in cache:
            result = cache[job_id]
        else:
            try:
                result = evaluator.evaluate(expr)
            except ValueError as e:
                print(f"Error evaluating job {job_id}: {e}")
                continue
            cache[job_id] = result

        used_cost += cost
        if isinstance(result, int):
            print(f"RESULT {job_id} {result}")
        else:
            print(f"RESULT {job_id} {result:.1f}")

    save_cache(cache)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python job_runner.py path/to/config.json")
        sys.exit(1)
    main(sys.argv[1])

import os
import sys
import xml.etree.ElementTree as ET
import requests
from urllib.parse import urljoin
from xml.etree.ElementTree import ParseError

def load_services_config():
    try:
        tree = ET.parse('services.xml')
        root = tree.getroot()
        services = {}
        for service in root.findall('service'):
            name = service.get('name')
            base_url = service.get('base_url')
            token_env = service.get('token_env')
            if name and base_url and token_env:
                services[name] = {'base_url': base_url, 'token_env': token_env}
        return services
    except ParseError:
        print("Error parsing services.xml")
        sys.exit(1)
    except FileNotFoundError:
        print("services.xml not found")
        sys.exit(1)

def validate_service_name(service_name, services):
    if service_name not in services:
        print(f"Unknown service: {service_name}")
        sys.exit(1)

def validate_token(token, service_name):
    if not token:
        print(f"Missing token for service: {service_name}")
        sys.exit(1)

def sanitize_path(path):
    if not path.startswith('/'):
        path = '/' + path
    return path.lstrip('/')

def main():
    if len(sys.argv) != 3:
        print("Usage: python script.py <service_name> <path>")
        sys.exit(1)

    service_name = sys.argv[1]
    path = sys.argv[2]

    services = load_services_config()

    validate_service_name(service_name, services)

    service = services[service_name]
    token_env = service['token_env']
    token = os.getenv(token_env)

    validate_token(token, service_name)

    base_url = service['base_url']
    final_url = urljoin(base_url, sanitize_path(path))
    headers = {'Authorization': f'Bearer {token}'}

    try:
        response = requests.get(final_url, headers=headers)
        print(f"URL: {final_url}")
        print(f"Status: {response.status_code}")
        try:
            response.raise_for_status()
            print(response.text)
        except UnicodeDecodeError:
            print(response.content)
    except requests.RequestException as e:
        print(f"Request failed: {e}")

if __name__ == "__main__":
    main()

import os
import sys
import time
import json
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import quote

def fetch_users():
    token = os.getenv('SERVICE_ACCESS_TOKEN')
    if not token:
        sys.stderr.write('SERVICE_ACCESS_TOKEN not set\n')
        sys.exit(1)

    user_ids = [line.strip() for line in sys.stdin if line.strip()]
    results = [None] * len(user_ids)

    def fetch_user_profile(user_id, index):
        url = f'https://example.com/api/users/{quote(user_id)}'
        headers = {'Authorization': f'Bearer {token}'}
        try:
            response = requests.get(url, headers=headers, timeout=10, verify=True)
            if response.status_code // 100 == 2:
                profile = response.json()
                results[index] = f"{profile['id']}\t{profile['name']}\t{profile['email']}"
            else:
                results[index] = f"FAILED {user_id}"
        except requests.RequestException as e:
            sys.stderr.write(f"Request failed for {user_id}: {e}\n")
            results[index] = f"FAILED {user_id}"

    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = {executor.submit(fetch_user_profile, user_id, i): i for i, user_id in enumerate(user_ids)}
        for future in as_completed(futures):
            time.sleep(0.5)

    for result in results:
        if result:
            print(result)

    sys.exit(0)

if __name__ == '__main__':
    fetch_users()

import sys
import xml.etree.ElementTree as ET
import requests
import json
import os
from urllib.parse import urlparse
from requests.exceptions import RequestException

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def fetch_endpoints(config_path):
    if not os.path.isfile(config_path):
        print("{}")
        return

    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(config_path, parser=parser)
        root = tree.getroot()
    except ET.ParseError:
        print("{}")
        return

    results = {}
    for endpoint in root.findall('endpoint'):
        name = endpoint.get('name')
        url = endpoint.get('url')

        if not name or not url or not is_valid_url(url):
            continue

        try:
            response = requests.get(url, timeout=10, verify=True)
            status = response.status_code
            body = response.text[:200]
        except RequestException:
            status = None
            body = ""

        results[name] = {
            "url": url,
            "status": status,
            "body": body
        }

    print(json.dumps(results))

