import sys
import requests
from xml.etree import ElementTree as ET
from xml.etree.ElementTree import ParseError
from html import escape
import ssl
import logging

def fetch_rss_feed(url):
    try:
        response = requests.get(url, timeout=10, verify=True)
        response.raise_for_status()
        parser = ET.XMLParser(forbid_dtd=True)
        return ET.fromstring(response.content, parser=parser)
    except (requests.RequestException, ParseError, ET.ParseError) as e:
        logging.error(f"Error fetching or parsing feed {url}: {e}")
        return None

def parse_rss_items(feed, max_items=5):
    items = []
    for item in feed.findall('.//item')[:max_items]:
        title = escape(item.find('title').text) if item.find('title') is not None else 'No Title'
        link = escape(item.find('link').text) if item.find('link') is not None else '#'
        pub_date = escape(item.find('pubDate').text) if item.find('pubDate') is not None else 'No Date'
        items.append((title, link, pub_date))
    return items

def generate_html(items):
    html_content = ['<!DOCTYPE html>', '<html lang="en">', '<head>', '<meta charset="UTF-8">',
                    '<title>RSS Digest</title>', '</head>', '<body>', '<h1>RSS Digest</h1>', '<ul>']
    for title, link, pub_date in items:
        html_content.append(f'<li><a href="{link}">{title}</a> ({pub_date})</li>')
    html_content.extend(['</ul>', '</body>', '</html>'])
    return '\n'.join(html_content)

def main(config_path, output_html_path):
    try:
        with open(config_path, 'r', encoding='utf-8') as config_file:
            feed_urls = [line.strip() for line in config_file if line.strip()]
    except (IOError, OSError) as e:
        logging.error(f"Error reading config file {config_path}: {e}")
        return

    all_items = []
    for url in feed_urls:
        feed = fetch_rss_feed(url)
        if feed is not None:
            items = parse_rss_items(feed)
            all_items.extend(items)

    html_output = generate_html(all_items)
    try:
        with open(output_html_path, 'w', encoding='utf-8') as output_file:
            output_file.write(html_output)
    except (IOError, OSError) as e:
        logging.error(f"Error writing to output file {output_html_path}: {e}")

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print("Usage: python rss_digest.py CONFIG_PATH OUTPUT_HTML_PATH")
    else:
        logging.basicConfig(level=logging.ERROR)
        main(sys.argv[1], sys.argv[2])

import sys
import xml.etree.ElementTree as ET
import requests
from datetime import datetime
import re
import os
from urllib.parse import urlparse

def log_message(service_name, status, reason=None):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} - {service_name} - {status}"
    if reason:
        log_entry += f" - {reason}"
    with open('check_services.log', 'a') as log_file:
        log_file.write(log_entry + '\n')

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def sanitize_url(url):
    if not is_valid_url(url):
        raise ValueError("Invalid URL")
    return url

def check_service(service_name, service_url):
    try:
        service_url = sanitize_url(service_url)
        response = requests.get(service_url, timeout=3, verify=True)
        if 200 <= response.status_code <= 299:
            log_message(service_name, "OK")
            print(f"{service_name} OK")
        else:
            log_message(service_name, "ERROR", f"Non-2xx status code: {response.status_code}")
            print(f"{service_name} ERROR")
    except requests.exceptions.Timeout:
        log_message(service_name, "ERROR", "Timeout")
        print(f"{service_name} ERROR")
    except requests.exceptions.RequestException as e:
        log_message(service_name, "ERROR", str(e))
        print(f"{service_name} ERROR")

def main():
    if len(sys.argv) != 2:
        print("Usage: python check_services.py CONFIG_XML_PATH")
        sys.exit(1)

    xml_path = sys.argv[1]
    if not os.path.isfile(xml_path):
        print(f"XML file not found: {xml_path}")
        sys.exit(1)

    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(xml_path, parser=parser)
        root = tree.getroot()
        for service in root.findall('service'):
            service_name = service.get('name')
            service_url = service.get('url')
            if service_name and service_url:
                check_service(service_name, service_url)
    except ET.ParseError as e:
        print(f"Error parsing XML file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import urllib.request
import ssl
import time
from html import escape
from urllib.parse import urlparse

def validate_url(url):
    parsed_url = urlparse(url)
    return parsed_url.scheme in ['http', 'https']

def fetch_data(data_url):
    context = ssl.create_default_context()
    request = urllib.request.Request(data_url, method='GET')
    try:
        with urllib.request.urlopen(request, context=context, timeout=10) as response:
            return json.loads(response.read().decode())
    except (urllib.error.URLError, json.JSONDecodeError, ssl.SSLError, TimeoutError) as e:
        raise RuntimeError(f"Failed to fetch data: {str(e)}")

def evaluate_expression(expr, row):
    allowed_names = {k: v for k, v in row.items() if isinstance(k, str) and k.isidentifier()}
    try:
        return str(eval(expr, {"__builtins__": {}}, allowed_names))
    except Exception as e:
        return f"Error: {str(e)}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python report_generator.py CONFIG_PATH")
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r') as config_file:
            config = json.load(config_file)
    except (IOError, json.JSONDecodeError) as e:
        print(f"Error reading config file: {str(e)}")
        sys.exit(1)

    title = config.get('title', '')
    data_url = config.get('data_url', '')
    expressions = config.get('expressions', [])

    if not validate_url(data_url):
        print("Invalid data URL")
        sys.exit(1)

    try:
        data = fetch_data(data_url)
    except RuntimeError as e:
        print(str(e))
        sys.exit(1)

    html_output = f"<h1>{escape(title)}</h1>\n<table>\n"

    header_row = "<tr>" + "".join(f"<th>{escape(expr)}</th>" for expr in expressions) + "</tr>\n"
    html_output += header_row

    for row in data:
        row_values = [evaluate_expression(expr, row) for expr in expressions]
        row_html = "<tr>" + "".join(f"<td>{escape(value)}</td>" for value in row_values) + "</tr>\n"
        html_output += row_html

    html_output += "</table>"
    print(html_output)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import hashlib
import hmac
import time
import re

def compute_digest(secret, token):
    return hmac.new(secret.encode(), token.encode(), hashlib.sha256).hexdigest().upper()

def validate_input(username, action):
    if not re.match(r'^[a-zA-Z0-9_-]+$', username):
        return False
    if action not in {'read', 'write', 'delete'}:
        return False
    return True

def main():
    if len(sys.argv) != 4:
        print("Usage: python auth_check.py CONFIG_PATH USERNAME ACTION")
        sys.exit(1)

    config_path, username, action = sys.argv[1:]

    if not validate_input(username, action):
        print("DENIED")
        sys.exit(1)

    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(config_path, parser=parser)
        root = tree.getroot()
    except ET.ParseError:
        print("DENIED")
        sys.exit(1)

    secret = root.find('secret').get('key')
    user = root.find(f"./user[@name='{username}']")

    if user is None:
        print("DENIED")
        sys.exit(1)

    token = sys.stdin.readline().strip()
    expected_digest = user.get('tokenDigest')

    if not hmac.compare_digest(compute_digest(secret, token), expected_digest):
        print("DENIED")
        sys.exit(1)

    roles = user.get('roles', '').split(',')
    allowed_actions = {
        'reader': {'read'},
        'writer': {'read', 'write'},
        'admin': {'read', 'write', 'delete'}
    }

    if any(action in allowed_actions.get(role, set()) for role in roles):
        print("ALLOWED")
    else:
        print("DENIED")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import html
import secrets
import hmac
import time

def secure_compare(a, b):
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

def generate_secure_token(original_token):
    return hmac.new(original_token.encode(), str(time.time()).encode(), secrets.token_algorithm).hexdigest()

def validate_xml_structure(root):
    if root.tag != 'config':
        return False
    sessions = root.find('sessions')
    if sessions is None:
        return False
    for session in sessions.findall('session'):
        if not all(session.find(tag) is not None for tag in ['user', 'token', 'role']):
            return False
    return True

def main():
    if len(sys.argv) != 3:
        print("Usage: python login_portal.py <config_path> <access_token>")
        return

    config_path = sys.argv[1]
    access_token = sys.argv[2]

    if not config_path.startswith('/secure/path/'):
        print("INVALID_TOKEN")
        return

    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(config_path, parser=parser)
        root = tree.getroot()
    except ET.ParseError:
        print("INVALID_TOKEN")
        return

    if not validate_xml_structure(root):
        print("INVALID_TOKEN")
        return

    sessions = root.find('sessions')
    for session in sessions.findall('session'):
        token = session.find('token').text
        if secure_compare(token, access_token):
            user = html.escape(session.find('user').text)
            role = html.escape(session.find('role').text)
            new_token = generate_secure_token(token)

            print(f"<html><head></head><body>")
            print(f"<h1>Welcome, {user}!</h1>")
            print(f"<p>Your new session token is: {new_token}</p>")
            print(f"<div id=\"dashboard\">")
            if role == 'admin':
                print(f"<h2>Admin dashboard</h2>")
                print(f"<ul><li>View metrics</li><li>Manage users</li><li>Review logs</li></ul>")
            else:
                print(f"<h2>User dashboard</h2>")
                print(f"<p>You have limited access.</p>")
            print(f"</div>")
            print(f"</body></html>")
            return

    print("INVALID_TOKEN")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json
import re
from xml.etree.ElementTree import ParseError

def evaluate_condition(condition, env):
    # Use a safe eval by only allowing certain operations
    allowed_names = {
        'user': env['user'],
        'token': env['token'],
        'action': env['action'],
        'params': env['params']
    }
    try:
        # Restrict eval to only allow access to allowed_names
        return eval(condition, {"__builtins__": None}, allowed_names)
    except Exception:
        return False

def validate_json_request(request):
    # Validate the structure of the JSON request
    if not isinstance(request, dict):
        return False
    if not all(key in request for key in ("user", "token", "action", "params")):
        return False
    if not isinstance(request["user"], str) or not isinstance(request["token"], str) or not isinstance(request["action"], str):
        return False
    if not isinstance(request["params"], dict):
        return False
    for key, value in request["params"].items():
        if not isinstance(key, str) or not isinstance(value, (str, int, float)):
            return False
    return True

def parse_xml_safe(xml_file_path):
    # Parse XML safely to prevent XXE attacks
    try:
        parser = ET.XMLParser(forbid_dtd=True)
        tree = ET.parse(xml_file_path, parser=parser)
        return tree.getroot()
    except (ParseError, FileNotFoundError):
        return None

def main():
    if len(sys.argv) != 2:
        print("DENIED")
        return

    xml_file_path = sys.argv[1]
    root = parse_xml_safe(xml_file_path)
    if root is None:
        print("DENIED")
        return

    try:
        request_json = sys.stdin.readline().strip()
        request = json.loads(request_json)
    except (json.JSONDecodeError, TypeError):
        print("DENIED")
        return

    if not validate_json_request(request):
        print("DENIED")
        return

    for policy in root.findall('policy'):
        token_prefix = policy.get('token_prefix')
        condition = policy.get('condition')
        policy_id = policy.get('id')

        if request['token'].startswith(token_prefix):
            env = {
                'user': request['user'],
                'token': request['token'],
                'action': request['action'],
                'params': request['params']
            }
            if evaluate_condition(condition, env):
                print(f"ALLOWED {policy_id}")
                return

    print("DENIED")

if __name__ == "__main__":
    main()

import sys
import json
import hashlib
import ast
import re
from collections import ChainMap

def is_safe_expression(expression):
    # Allow only safe operations and literals
    try:
        parsed = ast.parse(expression, mode='eval')
        for node in ast.walk(parsed):
            if not isinstance(node, (ast.Expression, ast.Str, ast.Num, ast.Name, ast.Load, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod, ast.Pow)):
                return False
        return True
    except SyntaxError:
        return False

def main():
    try:
        with open('users.json', 'r') as f:
            users = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        print("ERROR")
        sys.exit(1)

    try:
        input_data = json.loads(sys.stdin.readline().strip())
    except json.JSONDecodeError:
        print("ERROR")
        sys.exit(1)

    user_record = next((user for user in users if user['user'] == input_data['user']), None)
    if not user_record:
        print("ERROR")
        sys.exit(1)

    if input_data['role'] not in user_record['roles']:
        print("ERROR")
        sys.exit(1)

    payload = f"{input_data['user']}:{input_data['role']}"
    computed_token = hashlib.sha256(payload.encode()).hexdigest()

