import sys
import xml.etree.ElementTree as ET
import hashlib
import ast
import operator

class SafeEvaluator(ast.NodeVisitor):
    def __init__(self, variables):
        self.variables = variables
        self.operators = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.FloorDiv: operator.floordiv,
            ast.Mod: operator.mod,
            ast.Pow: operator.pow,
            ast.BitXor: operator.xor,
            ast.USub: operator.neg,
            ast.UAdd: operator.pos,
            ast.Lt: operator.lt,
            ast.LtE: operator.le,
            ast.Gt: operator.gt,
            ast.GtE: operator.ge,
            ast.Eq: operator.eq,
            ast.NotEq: operator.ne,
            ast.And: operator.and_,
            ast.Or: operator.or_,
        }

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        op = self.operators[type(node.op)]
        return op(left, right)

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        op = self.operators[type(node.op)]
        return op(operand)

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            if not self.operators[type(op)](left, right):
                return False
            left = right
        return True

    def visit_BoolOp(self, node):
        values = [self.visit(value) for value in node.values]
        op = all if isinstance(node.op, ast.And) else any
        return op(values)

    def visit_Name(self, node):
        if node.id in self.variables:
            return self.variables[node.id]
        raise NameError(f"Name '{node.id}' is not defined")

    def visit_Num(self, node):
        return node.n

    def visit_Expr(self, node):
        return self.visit(node.value)

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Module(self, node):
        return self.visit(node.body[0])

    def generic_visit(self, node):
        raise ValueError(f"Unsupported operation: {ast.dump(node)}")

def load_config(file_path):
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()
        if root.tag != 'config':
            raise ValueError("Root element is not 'config'")

        variables = {}
        secret_text = None

        for elem in root:
            if elem.tag == 'var':
                name = elem.get('name')
                value = int(elem.get('value'))
                variables[name] = value
            elif elem.tag == 'secret':
                secret_text = elem.get('text')

        if secret_text is None:
            raise ValueError("Missing <secret> element")

        secret_hash = int(hashlib.sha256(secret_text.encode()).hexdigest(), 16)
        variables['secret_hash'] = secret_hash

        return variables

    except Exception:
        print("CONFIG ERROR")
        sys.exit(1)

def evaluate_expressions(variables):
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            tree = ast.parse(line, mode='eval')
            evaluator = SafeEvaluator(variables)
            result = evaluator.visit(tree)
            print(result)
        except Exception:
            print("ERROR")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("CONFIG ERROR")
        sys.exit(1)

    config_path = sys.argv[1]
    variables = load_config(config_path)
    evaluate_expressions(variables)

import sys
import xml.etree.ElementTree as ET
from collections import defaultdict, deque
import re

def parse_config(file_path):
    tree = ET.parse(file_path, parser=ET.XMLParser(forbid_dtd=True))
    root = tree.getroot()
    window_seconds = int(root.get('window_seconds'))
    if window_seconds <= 0:
        raise ValueError("window_seconds must be a positive integer")
    clients = {}
    for client in root.findall('client'):
        client_id = client.get('id')
        max_active = int(client.get('max_active'))
        max_new = int(client.get('max_new'))
        tag = client.get('tag')
        if not client_id or max_active <= 0 or max_new <= 0 or not tag:
            raise ValueError("Invalid client configuration")
        clients[client_id] = {
            'max_active': max_active,
            'max_new': max_new,
            'tag': tag,
            'active_count': 0,
            'history': deque()
        }
    return window_seconds, clients

def calculate_signature(client_id, timestamp, action, tag):
    s = f"{client_id}|{timestamp}|{action}|{tag}"
    v = 0
    for c in s:
        u = ord(c)
        v = (v * 131 + u) & 0xFFFFFFFFFFFFFFFF
    return f"{v:016x}"

def process_requests(window_seconds, clients):
    for line in sys.stdin:
        line = line.strip()
        if not re.match(r'^[^ ]+ [0-9]+ (ALLOCATE|RELEASE)$', line):
            continue
        client_id, timestamp, action = line.split()
        timestamp = int(timestamp)
        if client_id not in clients:
            print(f"UNKNOWN {client_id}")
            continue

        client = clients[client_id]
        now = timestamp
        window_start = now - window_seconds

        # Remove outdated allocations
        while client['history'] and client['history'][0] < window_start:
            client['history'].popleft()

        if action == 'ALLOCATE':
            H = len(client['history'])
            if client['active_count'] < client['max_active'] and H < client['max_new']:
                client['active_count'] += 1
                client['history'].append(timestamp)
                signature = calculate_signature(client_id, timestamp, 'ALLOCATE', client['tag'])
                print(f"ALLOCATED {client_id} {timestamp} {signature}")
            else:
                print(f"THROTTLED {client_id} {timestamp}")
        elif action == 'RELEASE':
            if client['active_count'] > 0:
                client['active_count'] -= 1
                signature = calculate_signature(client_id, timestamp, 'RELEASE', client['tag'])
                print(f"RELEASED {client_id} {timestamp} {signature}")
            else:
                print(f"IGNORED {client_id} {timestamp}")

def main():
    if len(sys.argv) != 2:
        print("Usage: alloc_throttle.py CONFIG.xml")
        sys.exit(1)

    config_file = sys.argv[1]
    try:
        window_seconds, clients = parse_config(config_file)
    except (ET.ParseError, ValueError) as e:
        print(f"Error parsing configuration: {e}")
        sys.exit(1)

    try:
        process_requests(window_seconds, clients)
    except Exception as e:
        print(f"Error processing requests: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import ast
import operator
import re
import html

def parse_config(file_path):
    tree = ET.parse(file_path)
    root = tree.getroot()

    per_user_max = int(root.find('limits').get('per_user_max'))

    variables = {}
    for var in root.find('variables').findall('var'):
        name = var.get('name')
        value = float(var.get('value'))
        variables[name] = value

    return per_user_max, variables

def evaluate_expression(expression, variables):
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg
    }

    def eval_node(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            else:
                raise ValueError(f"Undefined variable: {html.escape(node.id)}")
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](left, right)
            else:
                raise ValueError(f"Unsupported operator: {op_type}")
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            op_type = type(node.op)
            if op_type in allowed_operators:
                return allowed_operators[op_type](operand)
            else:
                raise ValueError(f"Unsupported operator: {op_type}")
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

    try:
        tree = ast.parse(expression, mode='eval')
        return eval_node(tree.body)
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {str(e)}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <config_file>")
        sys.exit(1)

    config_file = sys.argv[1]
    per_user_max, variables = parse_config(config_file)

    user_evaluations = {}

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        match = re.match(r'^([^:]+):\s*(.+)$', line)
        if not match:
            print(f"ERROR INVALID INPUT")
            continue

        user_id, expression = match.groups()
        user_id = html.escape(user_id)

        if user_id not in user_evaluations:
            user_evaluations[user_id] = 0

        if user_evaluations[user_id] >= per_user_max:
            print(f"THROTTLED {user_id}")
        else:
            try:
                result = evaluate_expression(expression, variables)
                print(f"{user_id}: {result}")
                user_evaluations[user_id] += 1
            except ValueError:
                print(f"ERROR {user_id}")

if __name__ == "__main__":
    main()

import sys
import json
import hashlib
import hmac
import re
from html import escape

def is_valid_number(value):
    return isinstance(value, (int, float))

def sanitize_html(text):
    return escape(text)

def evaluate_expression(expr, variables):
    allowed_names = {k: v for k, v in variables.items() if is_valid_number(v)}
    code = compile(expr, "<string>", "eval")
    for name in code.co_names:
        if name not in allowed_names:
            raise ValueError(f"Use of name '{name}' is not allowed")
    return eval(code, {"__builtins__": {}}, allowed_names)

def main():
    if len(sys.argv) != 2:
        print("ERROR")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r', encoding='utf-8') as file:
            config = json.load(file)
    except (IOError, json.JSONDecodeError):
        print("ERROR")
        sys.exit(1)

    try:
        title = config['title']
        variables = config['variables']
        formulas = config['formulas']
    except KeyError:
        print("ERROR")
        sys.exit(1)

    if not isinstance(title, str) or not isinstance(variables, dict) or not isinstance(formulas, list):
        print("ERROR")
        sys.exit(1)

    results = []
    for formula in formulas:
        try:
            label = formula['label']
            expr = formula['expr']
            if not isinstance(label, str) or not isinstance(expr, str):
                raise ValueError("Invalid formula format")
            result = evaluate_expression(expr, variables)
            if not is_valid_number(result):
                raise ValueError("Expression did not evaluate to a number")
            results.append((label, expr, str(result)))
        except Exception:
            print("ERROR")
            sys.exit(1)

    summary_string = title + '|' + '|'.join(f"{label}={value}" for label, _, value in results)
    secret_key = b'secret_key'  # Replace with a secure key in production
    digest = hmac.new(secret_key, summary_string.encode('utf-8'), hashlib.sha256).hexdigest()

    print(f"<html><head><title>{sanitize_html(title)}</title></head><body>")
    print(f"<h1>{sanitize_html(title)}</h1>")
    print("<table><tr><th>Label</th><th>Expression</th><th>Value</th></tr>")
    for label, expr, value in results:
        print(f"<tr><td>{sanitize_html(label)}</td><td>{sanitize_html(expr)}</td><td>{sanitize_html(value)}</td></tr>")
    print("</table>")
    print(f'<div id="signature">{digest}</div>')
    print("</body></html>")

if __name__ == "__main__":
    main()
